<script setup>
import {ref,computed,onMounted} from 'vue'
import {voiceApi as api,stamp,labels} from '../voice/operations'
import VoiceDispositionForm from './VoiceDispositionForm.vue'
import VoiceLiveQueuePanel from './VoiceLiveQueuePanel.vue'
const props=defineProps({initialTab:{type:String,default:'reports'},allowedTabs:{type:Array,default:()=>['reports','lists','policies','live','origins']}})
const tab=ref(props.initialTab),catalog=ref(null),report=ref(null),error=ref(''),notice=ref(''),busy=ref(false),selected=ref(null),history=ref(null)
const filters=ref({from:'',to:'',campaign_id:'',user_id:'',method:'',status:'',phone:'',list_id:'',queue_id:'',pending_disposition:false,timezone:'America/Sao_Paulo',page:1})
const query=computed(()=>new URLSearchParams(Object.entries(filters.value).filter(([k,v])=>v!==''&&v!==false&&v!==null).map(([k,v])=>[k,v===true?'1':String(v)])).toString())
async function loadCatalog(){catalog.value=await api('/operations/catalog')}
async function loadReports(){report.value=await api('/operations/reports?'+query.value)}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
const list=ref(''),members=ref(null),listName=ref(''),listSource=ref(''),batch=ref(null),file=ref(null),memberReason=ref('')
const mapping=ref({delimiter:';',name_column:'nome',phone_column:'telefone',source:'',consent:false,consent_evidence:''})
async function loadMembers(page=1){members.value=list.value?await api('/operations/lists/'+list.value+'/members?page='+page):null;batch.value=null}
async function createList(){const l=await api('/operations/lists','POST',{name:listName.value,source:listSource.value});await loadCatalog();list.value=l.id;await loadMembers();listName.value='';notice.value='Lista criada.'}
async function preview(){const data=new FormData();data.append('file',file.value);for(const [k,v]of Object.entries(mapping.value))data.append(k,typeof v==='boolean'?(v?'1':'0'):v);batch.value=await api('/operations/lists/'+list.value+'/preview','POST',data)}
async function commit(){const b=await api('/operations/imports/'+batch.value.id+'/commit','POST',{});await loadMembers();batch.value=b;notice.value='Importação concluída; exclusões, autorizações e contadores existentes foram preservados.'}
async function member(m){await api('/operations/members/'+m.id,'PUT',{status:m.status==='active'?'removed':'active',reason:memberReason.value});await loadMembers()}
const campaign=ref(''),policy=ref(null)
function selectPolicy(){const old=catalog.value.policies.find(p=>p.campaign_id===Number(campaign.value));policy.value=old?JSON.parse(JSON.stringify(old)):{revision:0,list_id:null,daily_per_contact:3,global_daily:5,global_total:20,technical_limit:3,retry_minutes:{no_answer:60,busy:30,failed:120,cancelled:60},origin_mode:'configured',expires_at:null};policy.value.retry_minutes=Object.fromEntries(['no_answer','busy','failed','cancelled'].map(s=>[s,policy.value.retry_minutes?.[s]??old?.default_retry_minutes??60]));if(policy.value.expires_at){const d=new Date(policy.value.expires_at.replace(' ','T')+'Z');policy.value.expires_at=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}}
async function savePolicy(){const p=policy.value;await api('/operations/campaigns/'+campaign.value+'/policy','PUT',{revision:p.revision,list_id:p.list_id,daily_per_contact:p.daily_per_contact,global_daily:p.global_daily,global_total:p.global_total,technical_limit:p.technical_limit,retry_minutes:p.retry_minutes,origin_mode:p.origin_mode,expires_at:p.expires_at?new Date(p.expires_at).toISOString():null});await loadCatalog();selectPolicy();notice.value='Regras salvas. O máximo total e o limiar do WhatsApp continuam na configuração da campanha.'}
const code=ref({code:'',label:'',human:false,notes_required:false,active:true})
onMounted(()=>run(async()=>{await loadCatalog();if(tab.value==='reports')await loadReports()}))
</script>
<template><section class="operations"><h2>Operação do discador</h2><p>Chamadas reais, listas e filas. O atendimento encerra a abordagem e cancela o WhatsApp pendente.</p><nav v-if="allowedTabs.length>1" class="op-tabs"><button v-for="[key,label] in [['reports','Relatórios e tabulação'],['lists','Listas'],['policies','Regras de tentativas'],['live','Filas reais'],['origins','Números de saída']].filter(([key])=>allowedTabs.includes(key))" :key="key" class="secondary" :class="{chosen:tab===key}" @click="tab=key;if(key==='reports')run(loadReports)">{{label}}</button></nav><div v-if="error" role="alert" class="error">{{error}}</div><p v-if="notice" role="status">{{notice}}</p><template v-if="catalog">
<template v-if="tab==='reports'"><form class="table-card op-box" @submit.prevent="run(async()=>{filters.page=1;await loadReports()})"><div class="op-grid"><label>De<input v-model="filters.from" type="date"></label><label>Até<input v-model="filters.to" type="date"></label><label>Campanha<select v-model="filters.campaign_id"><option value="">Todas</option><option v-for="c in catalog.campaigns" :value="c.id">{{c.name}}</option></select></label><label>Atendente<select v-model="filters.user_id"><option value="">Todos com acesso</option><option v-for="u in catalog.agents" :value="u.id">{{u.name}}</option></select></label><label>Método<select v-model="filters.method"><option value="">Todos</option><option value="programmable_voice">Twilio API</option><option value="sip_trunk">SIP</option></select></label><label>Resultado técnico<select v-model="filters.status"><option value="">Todos</option><option v-for="s in ['pending','dialing','answered','completed','busy','no_answer','failed','cancelled','unknown']" :value="s">{{labels[s]}}</option></select></label><label>Telefone<input v-model="filters.phone" placeholder="+5511…"></label><label>Lista<select v-model="filters.list_id"><option value="">Todas</option><option v-for="l in catalog.lists" :value="l.id">{{l.name}}</option></select></label></div><label class="check"><input v-model="filters.pending_disposition" type="checkbox">Somente atendidas sem tabulação</label><button class="primary" :disabled="busy">Filtrar</button> <a :href="'/api/voice/operations/export?'+query" class="secondary">Exportar CSV</a><small>Datas em America/Sao_Paulo. Exportação em UTC. Até 10.000 chamadas por arquivo.</small></form>
<template v-if="report"><div class="op-stats"><article v-for="[key,label] in [['attempts','Tentativas iniciadas'],['answered','Atendidas pela telefonia'],['human_contacts','Contatos humanos confirmados'],['unclassified','Aguardando tabulação'],['pending','Sem encerramento confirmado'],['converted_contacts','Contatos convertidos']]" class="table-card"><strong>{{report.summary[key]||0}}</strong><span>{{label}}</span></article></div><p>Conversa: {{report.summary.conversation_seconds||0}} segundos. {{report.cost_notice}} <span v-for="c in report.costs">{{c.currency}} {{Number(c.amount).toFixed(4)}} · </span></p><div class="op-scroll table-card"><table><thead><tr><th>Contato / campanha</th><th>Origem / método</th><th>Resultado</th><th>Tabulação</th><th>Horário / duração</th><th>Ações</th></tr></thead><tbody><tr v-for="c in report.calls.data" :key="c.id"><td>{{c.contact_name}}<small>{{c.destination}} · {{c.campaign_name||'Avulsa'}} · {{c.agent_name}}</small></td><td>{{c.caller_id}}<small>{{c.method==='programmable_voice'?'Twilio API':'SIP'}} · {{c.environment==='homologation'?'Homologação':'Produção'}}</small></td><td>{{labels[c.status]}}<small>{{c.dial_status}} {{c.cause}}</small></td><td>{{c.disposition_label||'Não tabulada'}}<small v-if="c.callback_at">Retorno: {{stamp(c.callback_at)}}</small></td><td>{{stamp(c.started_at||c.created_at)}}<small>{{c.bill_seconds}} s</small><small v-for="cost in c.costs">{{cost.leg==='phone'?'Telefone':'Navegador'}}: {{cost.amount===null?'Preço pendente':cost.currency+' '+cost.amount}}</small></td><td><button v-if="c.capacity_released_at&&c.status!=='unknown'" class="secondary" @click="selected=c;history=null">{{c.disposition_revision?'Corrigir':'Tabular'}}</button><button class="secondary" @click="run(async()=>history=await api('/operations/calls/'+c.id+'/history'))">Histórico</button><button v-if="catalog.can_manage&&c.method==='programmable_voice'" class="secondary" @click="run(async()=>{await api('/operations/calls/'+c.id+'/costs','POST',{});await loadReports()})">Consultar custo</button></td></tr></tbody></table><p v-if="!report.calls.data.length">Nenhuma chamada nos filtros selecionados.</p></div><div class="op-tabs"><button class="secondary" :disabled="busy||report.calls.current_page===1" @click="run(async()=>{filters.page--;await loadReports()})">Anterior</button><span>Página {{report.calls.current_page}} de {{report.calls.last_page}} · {{report.calls.total}} chamadas</span><button class="secondary" :disabled="busy||report.calls.current_page>=report.calls.last_page" @click="run(async()=>{filters.page++;await loadReports()})">Próxima</button></div></template>
<article v-if="selected" class="table-card op-box"><VoiceDispositionForm :key="selected.id+':'+selected.disposition_revision" :call="selected" :codes="catalog.codes" @saved="selected=null;run(loadReports)" @cancel="selected=null"/></article><article v-if="history" class="table-card op-box"><h3>Histórico de correções</h3><p v-for="h in history">{{stamp(h.created_at)}} · revisão {{h.revision}} · {{h.label}} · {{h.notes}} · {{h.correction_reason}}</p><p v-if="!history.length">Sem tabulação registrada.</p></article>
<details v-if="catalog.can_manage" class="table-card op-box"><summary>Configurar opções de tabulação</summary><form @submit.prevent="run(async()=>{await api('/operations/codes','POST',code);await loadCatalog();notice='Opção salva.'})"><label>Opção existente<select @change="code={...catalog.codes.find(c=>c.code===$event.target.value)}"><option value="">Nova opção</option><option v-for="c in catalog.codes" :value="c.code">{{c.label}}</option></select></label><label>Identificador<input v-model="code.code" pattern="[a-z][a-z0-9_]{2,39}" required></label><label>Nome<input v-model="code.label" required maxlength="100"></label><label class="check"><input type="checkbox" v-model="code.human">Confirma conversa com humano</label><label class="check"><input type="checkbox" v-model="code.notes_required">Observação obrigatória</label><label class="check"><input type="checkbox" v-model="code.active">Disponível</label><button class="primary" :disabled="busy">Salvar opção</button></form></details></template>
<template v-if="tab==='lists'"><form v-if="catalog.can_manage" class="table-card op-box" @submit.prevent="run(createList)"><h3>Nova lista</h3><div class="op-grid"><label>Nome<input v-model="listName" required maxlength="160"></label><label>Origem dos contatos<input v-model="listSource" required maxlength="300"></label></div><button class="primary" :disabled="busy">Criar lista</button></form><label>Lista<select v-model="list" @change="run(()=>loadMembers())"><option value="">Selecione</option><option v-for="l in catalog.lists" :value="l.id">{{l.name}}</option></select></label><template v-if="list"><form v-if="catalog.can_manage" class="table-card op-box" @submit.prevent="run(preview)"><h3>Importar CSV ou XLSX</h3><p>Até 1.000 contatos e 2 MB. XLSX: primeira aba, telefone como texto. Duplicados e erros serão apresentados antes da confirmação.</p><label>Arquivo<input type="file" accept=".csv,.txt,.xlsx" required @change="file=$event.target.files[0];batch=null"></label><div class="op-grid"><label>Coluna do nome<input v-model="mapping.name_column" required></label><label>Coluna do telefone<input v-model="mapping.phone_column" required></label><label>Separador CSV<select v-model="mapping.delimiter"><option value=";">Ponto e vírgula</option><option value=",">Vírgula</option></select></label><label>Origem deste arquivo<input v-model="mapping.source" required maxlength="300"></label></div><label class="check"><input type="checkbox" v-model="mapping.consent">Há autorização documentada para os contatos novos</label><label v-if="mapping.consent">Evidência da autorização<textarea v-model="mapping.consent_evidence" required minlength="8" maxlength="2000"/></label><button class="primary" :disabled="busy">Validar arquivo</button></form><article v-if="batch" class="table-card op-box"><h3>Prévia da importação</h3><p>{{batch.summary.valid}} válidos · {{batch.summary.invalid}} inválidos · {{batch.status==='committed'?'Importação confirmada':'Aguardando confirmação'}}</p><p v-for="r in batch.preview">{{r.name}} · {{r.phone}}</p><p v-for="e in batch.errors">Linha {{e.line}}: {{e.message}}</p><a :href="'/api/voice/operations/imports/'+batch.id+'/errors'">Baixar relatório de erros</a> <button v-if="batch.status!=='committed'&&batch.summary.valid" class="primary" :disabled="busy" @click="run(commit)">Importar {{batch.summary.valid}} contatos válidos</button></article><article v-if="members" class="table-card op-box"><h3>Participação na lista</h3><label v-if="catalog.can_manage">Motivo para retirar ou reincluir<input v-model="memberReason" minlength="5" maxlength="300"></label><div class="op-scroll"><table><thead><tr><th>Contato</th><th>Situação</th><th>Motivo</th><th></th></tr></thead><tbody><tr v-for="m in members.data"><td>{{m.name}}<small>{{m.phone}}</small></td><td>{{m.status==='active'?'Na lista':'Retirado'}}<small>{{m.suppressed_at?'Excluído de abordagens':m.replied_at?'Atendimento iniciado':!m.consent?'Sem autorização':''}}</small></td><td>{{m.reason}}<small>{{m.attempts||0}} tentativas reais acumuladas</small><small v-for="e in m.eligibility||[]">{{e.campaign}}: {{e.reason||'Elegível'}}</small></td><td><button v-if="catalog.can_manage" class="secondary" :disabled="busy||memberReason.trim().length<5" @click="run(()=>member(m))">{{m.status==='active'?'Retirar':'Reincluir'}}</button></td></tr></tbody></table></div><p>Reincluir não zera tentativas nem remove bloqueios de autorização.</p><button class="secondary" :disabled="members.current_page===1||busy" @click="run(()=>loadMembers(members.current_page-1))">Anterior</button> {{members.current_page}} / {{members.last_page}} <button class="secondary" :disabled="members.current_page>=members.last_page||busy" @click="run(()=>loadMembers(members.current_page+1))">Próxima</button></article></template></template>
<template v-if="tab==='policies'"><p>Pause a campanha para editar. Máximo de tentativas, horário e envio de WhatsApp ficam nos cartões da cadência. Entre campanhas, prevalece o menor limite definido para o contato; o limite diário global usa UTC.</p><label>Campanha<select v-model="campaign" @change="selectPolicy"><option value="">Selecione</option><option v-for="c in catalog.campaigns" :value="c.id">{{c.name}} · {{c.status}}</option></select></label><form v-if="policy" class="table-card op-box" @submit.prevent="run(savePolicy)"><fieldset :disabled="!catalog.can_manage"><p v-if="policy.audience_id">Esta campanha usa uma lista do MA. Para mudar o público, abra o cartão Público da jornada.</p><label>Lista da campanha<select v-model="policy.list_id" :disabled="!!policy.audience_id"><option :value="null">Público escolhido na campanha</option><option v-for="l in catalog.lists" :value="l.id">{{l.name}}</option></select></label><div class="op-grid"><label>Tentativas por contato / dia na campanha<input type="number" v-model.number="policy.daily_per_contact" min="1" max="20" required></label><label>Tentativas por contato / dia entre campanhas<input type="number" v-model.number="policy.global_daily" min="1" max="100" required></label><label>Tentativas acumuladas entre campanhas<input type="number" v-model.number="policy.global_total" min="1" max="1000" required></label><label>Falhas técnicas por dia<input type="number" v-model.number="policy.technical_limit" min="1" max="10" required></label><label>Validade da campanha<input type="datetime-local" v-model="policy.expires_at"></label><label v-for="s in ['no_answer','busy','failed','cancelled']">Intervalo: {{labels[s]}} (min)<input type="number" v-model.number="policy.retry_minutes[s]" min="1" max="10080" required></label></div><p>Intervalos iguais ao padrão da campanha acompanham suas alterações. Valores diferentes são exceções por resultado.</p><label>Número de saída<select v-model="policy.origin_mode"><option value="configured">Origem configurada na conexão</option><option value="same_ddd">Aleatório entre origens autorizadas no DDD do cliente</option></select></label><p>Sem número habilitado no DDD, a chamada é impedida. Os números precisam estar autorizados pela Twilio. Alterar estas regras cancela os passos de WhatsApp ainda pendentes desta campanha.</p><button class="primary" :disabled="busy">Salvar regras</button></fieldset></form></template>
<VoiceLiveQueuePanel v-if="tab==='live'" :catalog="catalog"/>
<template v-if="tab==='origins'"><article class="table-card op-box"><h3>Origens autorizadas pela Twilio</h3><p>Sincroniza números de voz e identificadores verificados da conta. Não compra números. A escolha por DDD exige catálogo atualizado nas últimas 24 horas e origem habilitada. A autorização da origem também depende da rota utilizada.</p><button v-if="catalog.can_manage" class="primary" :disabled="busy" @click="run(async()=>{await api('/operations/origins/sync','POST',{});await loadCatalog();notice='Catálogo atualizado.'})">Sincronizar com Twilio</button><div class="op-scroll"><table><thead><tr><th>Número</th><th>DDD</th><th>Tipo</th><th>Verificado</th><th></th></tr></thead><tbody><tr v-for="o in catalog.origins"><td>{{o.number}}</td><td>{{o.ddd||'Internacional'}}</td><td>{{o.kind==='owned'?'Número da conta':'Identificador verificado'}}</td><td>{{stamp(o.verified_at)}}</td><td><button class="secondary" :disabled="busy" @click="run(async()=>{await api('/operations/origins/'+o.id,'PUT',{enabled:!o.enabled});await loadCatalog()})">{{o.enabled?'Desabilitar':'Habilitar'}}</button></td></tr></tbody></table></div><p v-if="!catalog.origins.length">Nenhuma origem sincronizada disponível.</p></article></template>
</template></section></template>
<style>
.operations .op-box{padding:24px;margin:20px 0}.operations .op-tabs{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0}.operations .chosen{background:#e9e0f6;color:#56377d}.operations label:not(.check){display:flex;flex-direction:column;gap:8px;margin-bottom:16px;font-size:13px}.operations .check{display:flex;flex-direction:row;align-items:center;gap:10px;margin:16px 0}.operations .check input{width:auto}.operations select{padding:10px;border:1px solid #ddd5e7;border-radius:8px;background:white}.operations .op-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.operations .op-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:20px 0}.operations .op-stats article{padding:18px}.operations .op-stats strong{display:block;font-size:28px}.operations .op-stats span{font-size:12px}.operations small{display:block;color:#776e80;font-size:12px;line-height:1.6}.operations p{line-height:1.7}.operations .op-scroll{overflow:auto}.operations td{white-space:normal;min-width:130px}.operations td button{margin:3px}.operations fieldset{border:0;padding:0}.operations button:disabled{opacity:.5}.operations summary{cursor:pointer;font-weight:600}.operations form{margin-top:14px}
</style>
